    const open = await (await send(tasksPath, 'POST', { title: 'Open' })).json();
    const other = await (await send(otherTasksPath, 'POST', { title: 'Other' })).json();
    const projects = [
      { ...first, totalCount: 2, completedCount: 1 },
      { ...second, totalCount: 1 },
    ];
    for (const title of ['', ' \t\n ', null, 42]) {
